:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #6c63ff;
  --accent-hover: #5a52d5;
  --light-on: #ffd166;
  --light-off: #3a3a55;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 32px 28px;
  box-shadow: var(--shadow);
  width: 100%;
  max-width: 420px;
  text-align: center;
}

h1 {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  margin-bottom: 4px;
}

.subtitle {
  font-size: 1rem;
  color: #b0b0c8;
  margin-bottom: 24px;
}

.board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 24px;
}

.cell {
  aspect-ratio: 1 / 1;
  border: none;
  border-radius: 14px;
  background: var(--light-off);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  font-size: 0;
  position: relative;
}

.cell::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 14px;
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.05);
  pointer-events: none;
}

.cell.on {
  background: var(--light-on);
  box-shadow: 0 0 12px rgba(255, 209, 102, 0.6);
}

.cell:hover {
  transform: scale(1.04);
}

.cell:active {
  transform: scale(0.96);
}

.cell:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.status {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 24px;
  min-height: 3em;
}

.moves {
  font-size: 1.1rem;
  color: #c8c8e0;
}

.win-message {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--light-on);
  min-height: 1.5em;
}

.btn {
  display: inline-block;
  width: 100%;
  padding: 14px 20px;
  font-size: 1.1rem;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 14px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:active {
  transform: scale(0.97);
}

.btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 3px;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 18px;
  }
  h1 {
    font-size: 1.6rem;
  }
  .board {
    gap: 8px;
  }
}

(function () {
  'use strict';

  const SIZE = 3;
  const boardEl = document.getElementById('board');
  const moveCountEl = document.getElementById('moveCount');
  const winMessageEl = document.getElementById('winMessage');
  const newPuzzleBtn = document.getElementById('newPuzzleBtn');

  let grid = [];
  let moves = 0;
  let solved = false;

  function createGrid() {
    return Array.from({ length: SIZE }, () => Array(SIZE).fill(false));
  }

  function randomizeGrid() {
    grid = createGrid();
    // Generate a solvable puzzle by applying random toggles from the all-off state
    for (let i = 0; i < SIZE; i++) {
      for (let j = 0; j < SIZE; j++) {
        if (Math.random() < 0.5) {
          toggleCell(i, j);
        }
      }
    }
    // Ensure the puzzle is not already solved
    if (isSolved()) {
      toggleCell(0, 0);
    }
  }

  function toggleCell(row, col) {
    const directions = [
      [0, 0],
      [-1, 0],
      [1, 0],
      [0, -1],
      [0, 1]
    ];
    for (const [dr, dc] of directions) {
      const r = row + dr;
      const c = col + dc;
      if (r >= 0 && r < SIZE && c >= 0 && c < SIZE) {
        grid[r][c] = !grid[r][c];
      }
    }
  }

  function isSolved() {
    return grid.every(row => row.every(cell => !cell));
  }

  function render() {
    boardEl.innerHTML = '';
    for (let i = 0; i < SIZE; i++) {
      for (let j = 0; j < SIZE; j++) {
        const btn = document.createElement('button');
        btn.className = 'cell' + (grid[i][j] ? ' on' : '');
        btn.setAttribute('aria-label', `Row ${i + 1}, column ${j + 1}, ${grid[i][j] ? 'on' : 'off'}`);
        btn.setAttribute('role', 'gridcell');
        btn.dataset.row = i;
        btn.dataset.col = j;
        btn.addEventListener('click', handleCellClick);
        boardEl.appendChild(btn);
      }
    }
    moveCountEl.textContent = `Moves: ${moves}`;
  }

  function handleCellClick(e) {
    if (solved) return;
    const row = parseInt(e.currentTarget.dataset.row, 10);
    const col = parseInt(e.currentTarget.dataset.col, 10);
    toggleCell(row, col);
    moves++;
    render();
    checkWin();
  }

  function checkWin() {
    if (isSolved()) {
      solved = true;
      winMessageEl.textContent = `You win! Solved in ${moves} move${moves !== 1 ? 's' : ''}.`;
    } else {
      winMessageEl.textContent = '';
    }
  }

  function newGame() {
    randomizeGrid();
    moves = 0;
    solved = false;
    winMessageEl.textContent = '';
    render();
  }

  newPuzzleBtn.addEventListener('click', newGame);

  // Initialize
  newGame();
})();
